import 'dotenv/config';
import { PrismaMariaDb } from '@prisma/adapter-mariadb';
import { PrismaPg } from '@prisma/adapter-pg';
// Generated by `npx prisma generate` (output set in prisma/schema.prisma).
// Node 22.18+ loads the generated TypeScript files without a build step.
import { PrismaClient } from '../generated/prisma/client.ts';

if (!process.env.DATABASE_URL) {
    throw new Error('DATABASE_URL is not set (expected in .env)');
}

// Prisma 7 connects through a driver adapter, chosen from the DATABASE_URL scheme so
// the same code serves MySQL and PostgreSQL (schema.prisma's provider must match):
// - postgres:// or postgresql:// -> @prisma/adapter-pg
// - mysql:// -> @prisma/adapter-mariadb; allowPublicKeyRetrieval lets the driver
//   complete MySQL 8 caching_sha2_password authentication on a non-TLS connection.
function createAdapter(databaseUrl) {
    const url = new URL(databaseUrl);
    if (url.protocol === 'postgres:' || url.protocol === 'postgresql:') {
        return new PrismaPg({ connectionString: databaseUrl });
    }
    url.searchParams.set('allowPublicKeyRetrieval', 'true');
    return new PrismaMariaDb(url.toString());
}

export const prisma = new PrismaClient({ adapter: createAdapter(process.env.DATABASE_URL) });
